// Checkout conversion fix module
// Ensures paidEvents are recorded when checkout completes

const { logEvent } = require('./eventLogger');

module.exports = function fixCheckoutConversion(req, res, next) {
  const originalJson = res.json.bind(res);
  res.json = function (body) {
    if (res.statusCode === 200 && req.path === '/api/checkout/complete') {
      logEvent('paidEvent', {
        userId: req.user?.id || 'anonymous',
        amount: req.body?.amount || 0,
        timestamp: new Date().toISOString()
      });
    }
    return originalJson(body);
  };
  next();
};
